<?php

use App\Http\Controllers\ProfileController;
use App\Http\Controllers\FieldToolController;
use Illuminate\Support\Facades\DB;
use App\Http\Controllers\PaymentController;
use App\Http\Controllers\BulkGeneratorController;
use Illuminate\Support\Facades\Route;

Route::get('/', function () {
    return view('welcome');
});

Route::get('/dashboard', function () {
    $userId = auth()->id();

    // Total FDT reports generated by this user
    $fieldReports = DB::table('generation_logs')
        ->where('user_id', $userId)
        ->where('tool_type', 'field_tool')
        ->count();

    // Total bulk files generated by this user
    $bulkFiles = DB::table('generation_logs')
        ->where('user_id', $userId)
        ->where('tool_type', 'bulk_generator')
        ->count();

    // Total layers generated by this user
    $bulkLayers = DB::table('generation_logs')
        ->where('user_id', $userId)
        ->where('tool_type', 'bulk_generator')
        ->sum('quantity');

    return view('dashboard', compact(
        'fieldReports',
        'bulkFiles',
        'bulkLayers'
    ));
})->middleware(['auth', 'verified'])->name('dashboard');
Route::middleware('auth')->group(function () {
    // Profile Routes
    Route::get('/profile', [ProfileController::class, 'edit'])->name('profile.edit');
    Route::patch('/profile', [ProfileController::class, 'update'])->name('profile.update');
    Route::delete('/profile', [ProfileController::class, 'destroy'])->name('profile.destroy');
    
    // --- Tool 1 Routes ---
    Route::get('/field-tool', [FieldToolController::class, 'index'])->name('field-tool.index');
    Route::post('/field-tool/generate', [FieldToolController::class, 'generateExcel'])->name('field-tool.generate');

    // --- Pricing & Payment Routes ---
    Route::get('/pricing', function () {
        return view('pricing');
    })->name('pricing');

    Route::post('/buy-field-tool', [PaymentController::class, 'buyFieldTool'])->name('buy.field.tool');
    Route::post('/subscribe/monthly', [PaymentController::class, 'subscribeMonthly'])->name('subscribe.monthly');
    Route::post('/subscribe/yearly', [PaymentController::class, 'subscribeYearly'])->name('subscribe.yearly');
    
    // --- Tool 2 Routes ---
    Route::get('/bulk-generator', [BulkGeneratorController::class, 'index'])->name('bulk.index');
    Route::post('/bulk-generator/generate', [BulkGeneratorController::class, 'generate'])->name('bulk.generate');
});

require __DIR__.'/auth.php';